package de.lazytv.pro.cms;
import android.app.*;import android.os.*;import android.webkit.*;import android.widget.*;
public class EmbeddedWebActivity extends Activity{protected void onCreate(Bundle b){super.onCreate(b);WebView w=new WebView(this);setContentView(w);WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setMediaPlaybackRequiresUserGesture(false);w.setWebViewClient(new WebViewClient());String u=getIntent().getStringExtra("url");if(u!=null){if(u.contains("youtu.be/")){String id=u.substring(u.lastIndexOf('/')+1).split("\\?")[0];u="https://www.youtube.com/embed/"+id+"?playsinline=1";}else if(u.contains("youtube.com/watch")){android.net.Uri x=android.net.Uri.parse(u);u="https://www.youtube.com/embed/"+x.getQueryParameter("v")+"?playsinline=1";}else if(u.contains("dailymotion.com/video/")){String id=u.substring(u.lastIndexOf('/')+1).split("\\?")[0];u="https://www.dailymotion.com/embed/video/"+id;}w.loadUrl(u);}}}